#include <cassert>
#include <climits>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>
static_assert(INT_MIN == (-2147483647 - 1) && INT_MAX == 2147483647, "32-bit int required");
int maximum_without_comparison(int a, int b) {
    // 뺄셈을 먼저 64비트로 넓혀 안전하게 계산합니다.
    const std::int64_t x = a, y = b;
    const std::int64_t difference = x - y;
    // 음수의 unsigned 변환은 2^64를 법으로 한 값입니다.
    const std::uint64_t sign = static_cast<std::uint64_t>(difference) >> 63;
    const std::int64_t take_a = static_cast<std::int64_t>(1U - sign);
    // 계수는 0 또는 1이고 한쪽만 선택됩니다.
    return static_cast<int>(take_a * x + (1 - take_a) * y);
}
// 정수 하나는 공백으로 나눈 토큰 전체여야 합니다. 1+2를 두 수로 읽지 않습니다.
bool read_integer(std::istream& input, long long& value) {
    std::string token;
    if (!(input >> token)) return false;
    const std::size_t first = (token[0] == '+' || token[0] == '-') ? 1 : 0;
    if (first == token.size()) return false;
    for (std::size_t i = first; i < token.size(); ++i)
        if (token[i] < '0' || token[i] > '9') return false;
    std::istringstream parser(token);
    parser >> value;
    return !parser.fail() && parser.eof();
}

int main() {
    // 파싱의 범위 검사는 허용합니다. 비교 금지는 최댓값 선택 함수 내부의 규칙입니다.
    long long a=0,b=0;
    if((!read_integer(std::cin,a)||!read_integer(std::cin,b))||a<INT_MIN||a>INT_MAX||b<INT_MIN||b>INT_MAX)return 1;
    std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
    std::cout<<maximum_without_comparison(static_cast<int>(a),static_cast<int>(b))<<'\n';
    return std::cout?0:1;
}
